-- Hyprland configuration.
--
-- Ported from hyprland.conf — hyprlang is deprecated as of Hyprland 0.55.
-- API reference:    /usr/share/hypr/stubs/hl.meta.lua
-- Default example:  /usr/share/hypr/hyprland.lua
-- Wiki:             https://wiki.hypr.land/Configuring/

-- Border/group colours are generated by DankMaterialShell (matugen) into
-- ~/.config/hypr/dms/colors.lua and ~/.config/hypr/borders.lua on every wallpaper
-- change. They are read with io rather than require so Hyprland does not register
-- them for autoreload: that reload stalled the shell mid-crossfade. theme-apply pushes the same colours live via hyprctl keywords.
local function load_colours(name)
    local f = io.open(os.getenv("HOME") .. "/.config/hypr/" .. name, "r")
    if not f then return end
    local chunk, err = load(f:read("*a"), "@" .. name)
    f:close()
    if chunk then chunk() else print("hyprland.lua: " .. tostring(err)) end
end
load_colours("dms/colors.lua")
load_colours("borders.lua")

-- Machine-local additions for projects that are not published: autostart commands,
-- keybinds and layer rules. They live in ~/.config/hypr/local.lua, which this repo
-- deliberately does not track — it is public, and an unreleased project's name and
-- paths are not something a dotfiles repo should announce. Read the same way as the
-- colours above (io + load, never require) so Hyprland does not watch it for reload.
-- The file returns a table:
--   return {
--     autostart   = { "cmd --flag" },
--     binds       = { { key = "SUPER + Y", cmd = "…", desc = "…" } },
--     layer_rules = { { name = "…", match = { namespace = "…" }, animation = "none" } },
--   }
local local_conf = {}
do
    local f = io.open(os.getenv("HOME") .. "/.config/hypr/local.lua", "r")
    if f then
        local chunk, err = load(f:read("*a"), "@local.lua")
        f:close()
        if chunk then
            local ok, t = pcall(chunk)
            if ok and type(t) == "table" then
                local_conf = t
            else
                print("hyprland.lua: local.lua did not return a table: " .. tostring(t))
            end
        else
            print("hyprland.lua: " .. tostring(err))
        end
    end
end


