hl.window_rule({
    name  = "spotify-workspace",
    match = { class = "^([Ss]potify)$" },

    workspace = "8 silent",
})

hl.window_rule({
    name  = "discord-workspace",
    match = { class = "^(discord)$" },

    workspace = "9 silent",
})

hl.window_rule({
    name  = "notion-workspace",
    match = { class = "^([Nn]otion|notion-app|notion-app-electron)$" },

    workspace = "7 silent",
})

-- Claude Desktop deliberately has NO workspace rule. It is launched on demand and
-- should open on the active workspace; relaunching it while it is open jumps to
-- its window instead (see ~/.local/bin/claude-focus-or-launch and the desktop
-- entry override in ~/.local/share/applications/). To pin it again, restore:
--   hl.window_rule({ name = "claude-workspace",
--       match = { class = "^(com\\.anthropic\\.[Cc]laude(-desktop)?|[Cc]laude)$" },
--       workspace = "6 silent" })

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})


-----------------
---- PLUGINS ----
-----------------

-- Plugins built from local, unpublished sources are listed in ~/.config/hypr/local.lua
-- (plugins = { "/path/to/plugin.so" }), so their paths stay out of this public repo.
for _, so in ipairs(local_conf.plugins or {}) do
    hl.plugin.load(so)
end
